const base = 'https://college-essay-edge.vercel.app';

async function run() {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  const results = [];
  const submitName = /Find the strongest direction|Show me possible directions|See what's here/i;

  // F1
  await page.goto(base + '/start');
  await page.getByLabel('Your notes or draft').fill('I spent three summers volunteering at the hospital, and I thought I was helping. In my third summer, a nurse pulled me aside and said I was just getting in the way. That conversation changed how I think about service.');
  await page.getByRole('button', { name: submitName }).click();
  await page.waitForURL(/\/start\/(reflecting|direction)/, { timeout: 20000 });
  results.push(['F1', page.url()]);

  // F3
  await page.goto(base + '/start');
  await page.getByLabel('Your notes or draft').fill('I like sports but I am not great at them.');
  await page.getByRole('button', { name: submitName }).click();
  await page.waitForURL(/\/start\/(question|blocked)/, { timeout: 20000 });
  results.push(['F3', page.url()]);

  // F4
  await page.goto(base + '/start');
  await page.getByLabel('Your notes or draft').fill('I am good at everything.');
  await page.getByRole('button', { name: submitName }).click();
  await page.waitForURL('**/start/blocked', { timeout: 20000 });
  results.push(['F4', page.url()]);

  for (const [k, v] of results) console.log(k + ': ' + v);
  await browser.close();
}

run().catch((e) => { console.error(e); process.exit(1); });
EOF

