set -euo pipefail
BASE="https://college-essay-edge.vercel.app"

curl -sS "$BASE/" > /tmp/phase6_home.html
if grep -Eq "Find the strongest story angle|Find your strongest college admissions essay theme" /tmp/phase6_home.html; then echo "home_render_ok"; else echo "home_render_fail"; exit 1; fi

curl -sS "$BASE/start" > /tmp/phase6_start.html
if grep -Eq "Paste rough notes|Find the strongest direction|Show me possible directions" /tmp/phase6_start.html; then echo "start_render_ok"; else echo "start_render_fail"; exit 1; fi

cat > /tmp/phase6_api_smoke.mjs <<'NODE'
const base = 'https://college-essay-edge.vercel.app';
const cases = [
  ['blank_page_candidate', 'I have no idea what to write about for my essay.'],
  ['topic_probe_candidate', 'Can I write about helping in robotics club?'],
  ['strong_direction_candidate', 'In my third summer at the hospital, a nurse told me I was in the way, and that changed how I showed up and listened.']
];

for (const [label, raw_input] of cases) {
  const res = await fetch(`${base}/api/intake/session`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ raw_input })
  });
  const body = await res.text();
  let json = {};
  try { json = JSON.parse(body); } catch {}

  const out = {
    label,
    status: res.status,
    product_mode: json.product_mode ?? null,
    top_level_blank_page_route: json.top_level_blank_page_route ?? null,
    blank_page_mode: json.blank_page_mode ?? null,
    has_blank_page_intake_payload: Boolean(json.blank_page_intake_payload),
    has_sharpening_question: Boolean(json.sharpening_question),
  };
  console.log(JSON.stringify(out));
}
NODE

